// Vérifie l'événement de La Joconde Jumelle : signature HMAC-SHA256 de « horodatage.corps » avec le
// secret partagé (LJJ_SHARED_SECRET), horodatage récent (5 min), identifiant d'événement jamais traité.
// Réponse : 401 si la signature est invalide, 200 pour un doublon (déjà traité), 202 sinon.
const crypto = require('crypto');
const secret = $env.LJJ_SHARED_SECRET || '';
const MAX_SKEW_MS = 5 * 60 * 1000;
const KEEP_MS = 7 * 24 * 60 * 60 * 1000;

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const timestamp = String(headers['x-ljj-timestamp'] || '');
const signature = String(headers['x-ljj-signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + JSON.stringify(body)).digest('hex');
const signed = secret.length >= 32 && signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() - Number(timestamp)) <= MAX_SKEW_MS;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!signed || !fresh || body.type !== 'PARENT_COMMUNICATION_APPROVED' || !uuid.test(body.eventId || '') || !uuid.test(body.communicationId || '')) {
  return [{ json: { accepted: false, statusCode: 401, response: { error: 'INVALID_SIGNATURE' } } }];
}

// Dédoublonnage : identifiants traités gardés 7 jours dans les données statiques du workflow.
const store = $getWorkflowStaticData('global');
const seen = store.seenEvents || {};
const now = Date.now();
for (const id of Object.keys(seen)) if (now - seen[id] > KEEP_MS) delete seen[id];
if (seen[body.eventId]) {
  store.seenEvents = seen;
  return [{ json: { accepted: false, statusCode: 200, response: { received: true, duplicate: true } } }];
}
seen[body.eventId] = now;
store.seenEvents = seen;
return [{ json: { accepted: true, statusCode: 202, response: { received: true }, eventId: body.eventId, communicationId: body.communicationId } }];

// Une entrée par canal activé pour lequel le représentant a une coordonnée (calculé par l'API).
// Aucune remarque ni aucun vocal : seulement l'invitation à lire le message dans l'espace parent.
const event = $('Événement accepté').first().json;
const data = $input.first().json;
return (data.channels || []).map((channel) => ({
  json: {
    eventId: event.eventId,
    communicationId: data.communicationId,
    channel,
    recipientFirstName: data.recipient.firstName,
    email: data.recipient.email || null,
    phone: data.recipient.phone || null,
    studentFirstName: data.student.firstName,
    senderName: data.senderName,
    link: data.link,
  },
}));

// Canal EMAIL uniquement ; le lien avec l'entrée d'origine est conservé.
return $input.all()
  .map((item, index) => ({ item, index }))
  .filter(({ item }) => item.json.channel === 'EMAIL')
  .map(({ item, index }) => ({ json: item.json, pairedItem: { item: index } }));

// Canal WHATSAPP uniquement ; le lien avec l'entrée d'origine est conservé.
return $input.all()
  .map((item, index) => ({ item, index }))
  .filter(({ item }) => item.json.channel === 'WHATSAPP')
  .map(({ item, index }) => ({ json: item.json, pairedItem: { item: index } }));

// Compte rendu de livraison pour La Joconde Jumelle (idempotent côté API).
const src = $('Canal e-mail').item.json;
return { json: {
  eventId: src.eventId,
  communicationId: src.communicationId,
  channel: src.channel,
  status: 'SENT',
  providerMessageId: String($json.messageId || ($json.messages && $json.messages[0] && $json.messages[0].id) || '').slice(0, 200) || undefined,
} };

// Compte rendu de livraison pour La Joconde Jumelle (idempotent côté API).
const src = $('Canal e-mail').item.json;
return { json: {
  eventId: src.eventId,
  communicationId: src.communicationId,
  channel: src.channel,
  status: 'FAILED',
  // Erreur du fournisseur sans donnée personnelle : adresses et numéros masqués, 500 caractères au plus.
  error: String(($json.error && ($json.error.message || $json.error)) || 'Erreur du fournisseur')
    .replace(/[^\s@]+@[^\s@]+/g, '[adresse masquée]')
    .replace(/\+?\d[\d\s().-]{6,}\d/g, '[numéro masqué]')
    .slice(0, 500),
} };

// Compte rendu de livraison pour La Joconde Jumelle (idempotent côté API).
const src = $('Canal WhatsApp').item.json;
return { json: {
  eventId: src.eventId,
  communicationId: src.communicationId,
  channel: src.channel,
  status: 'SENT',
  providerMessageId: String($json.messageId || ($json.messages && $json.messages[0] && $json.messages[0].id) || '').slice(0, 200) || undefined,
} };

// Compte rendu de livraison pour La Joconde Jumelle (idempotent côté API).
const src = $('Canal WhatsApp').item.json;
return { json: {
  eventId: src.eventId,
  communicationId: src.communicationId,
  channel: src.channel,
  status: 'FAILED',
  // Erreur du fournisseur sans donnée personnelle : adresses et numéros masqués, 500 caractères au plus.
  error: String(($json.error && ($json.error.message || $json.error)) || 'Erreur du fournisseur')
    .replace(/[^\s@]+@[^\s@]+/g, '[adresse masquée]')
    .replace(/\+?\d[\d\s().-]{6,}\d/g, '[numéro masqué]')
    .slice(0, 500),
} };
